#![forbid(unsafe_code)]
// Proves: CL-040-01, CL-040-03; TC-012-001. Hand-constructed NetworkMessage byte vectors
// (tests/vectors/udp/construct.py from WSJT-X NetworkMessage.hpp, Python struct, exact)
// against the encoder and the inbound parser; never generated by the Rust encoder.
use serde_json::{Value, json};
use wstx_rust::network_message::{self as nm, Inbound};

fn vectors() -> Vec<(String, Value)> {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/vectors/udp");
    let mut out: Vec<(String, Value)> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .map(|p| {
            let v: Value = serde_json::from_slice(&std::fs::read(&p).unwrap()).unwrap();
            (p.file_name().unwrap().to_string_lossy().into_owned(), v)
        })
        .collect();
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}
fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}
fn s(v: &Value, k: &str) -> String {
    v[k].as_str().unwrap().to_owned()
}
fn u(v: &Value, k: &str) -> u64 {
    v[k].as_u64().unwrap()
}
fn encode(i: &Value) -> Vec<u8> {
    let schema = u(i, "schema") as u32;
    let id = "WSTX-Rust";
    match i["kind"].as_str().unwrap() {
        "heartbeat" => nm::heartbeat(schema, id, &s(i, "version"), &s(i, "revision")),
        "status" => nm::status(
            schema,
            id,
            &nm::Status {
                dial_hz: u(i, "dial_hz"),
                mode: s(i, "mode"),
                dx_call: s(i, "dx_call"),
                report: s(i, "report"),
                tx_mode: s(i, "tx_mode"),
                tx_enabled: i["tx_enabled"] == true,
                transmitting: i["transmitting"] == true,
                decoding: i["decoding"] == true,
                rx_df: u(i, "rx_df") as u32,
                tx_df: u(i, "tx_df") as u32,
                de_call: s(i, "de_call"),
                de_grid: s(i, "de_grid"),
                dx_grid: s(i, "dx_grid"),
                tx_watchdog: i["tx_watchdog"] == true,
                sub_mode: s(i, "sub_mode"),
                fast_mode: i["fast_mode"] == true,
                special_operation: u(i, "special_operation") as u8,
                frequency_tolerance: u(i, "frequency_tolerance") as u32,
                tr_period: u(i, "tr_period") as u32,
                configuration_name: s(i, "configuration_name"),
                tx_message: s(i, "tx_message"),
            },
        ),
        "decode" => nm::decode(
            schema,
            id,
            i["new"] == true,
            &nm::Decode {
                time_ms: u(i, "time_ms") as u32,
                snr: i["snr"].as_i64().unwrap() as i32,
                delta_time: i["delta_time"].as_f64().unwrap() as f32,
                delta_frequency: u(i, "delta_frequency") as u32,
                mode: s(i, "mode"),
                message: s(i, "message"),
                low_confidence: false,
                off_air: false,
            },
        ),
        "clear" => nm::clear(schema, id),
        "close" => nm::close(schema, id),
        "qso_logged" => nm::qso_logged(
            schema,
            id,
            &nm::Logged {
                time_off: nm::DateTime::from_unix_ms(i["time_off_ms"].as_i64().unwrap()),
                dx_call: s(i, "dx_call"),
                dx_grid: s(i, "dx_grid"),
                tx_frequency_hz: u(i, "tx_frequency_hz"),
                mode: s(i, "mode"),
                report_sent: s(i, "report_sent"),
                report_received: s(i, "report_received"),
                tx_power: s(i, "tx_power"),
                comments: s(i, "comments"),
                name: s(i, "name"),
                time_on: nm::DateTime::from_unix_ms(i["time_on_ms"].as_i64().unwrap()),
                operator_call: s(i, "operator_call"),
                my_call: s(i, "my_call"),
                my_grid: s(i, "my_grid"),
            },
        ),
        "logged_adif" => nm::logged_adif(schema, id, &s(i, "adif")),
        other => panic!("unknown vector kind {other}"),
    }
}
fn color(c: nm::Color) -> Value {
    c.map_or(Value::Null, |(r, g, b)| json!([r, g, b]))
}
fn shown(d: &nm::Datagram) -> Value {
    let mut v = match &d.message {
        Inbound::Heartbeat {
            max_schema,
            version,
            revision,
        } => {
            json!({"type":"heartbeat","max_schema":max_schema,"version":version,"revision":revision})
        }
        Inbound::Clear { window } => json!({"type":"clear","window":window}),
        Inbound::Reply {
            time_ms,
            snr,
            delta_time,
            delta_frequency,
            mode,
            message,
            low_confidence,
            modifiers,
        } => json!({"type":"reply","time_ms":time_ms,"snr":snr,"delta_time":delta_time,
            "delta_frequency":delta_frequency,"mode":mode,"message":message,
            "low_confidence":low_confidence,"modifiers":modifiers}),
        Inbound::Close => json!({"type":"close"}),
        Inbound::Replay => json!({"type":"replay"}),
        Inbound::HaltTx { auto_only } => json!({"type":"halt_tx","auto_only":auto_only}),
        Inbound::FreeText { text, send } => json!({"type":"free_text","text":text,"send":send}),
        Inbound::Location { location } => json!({"type":"location","location":location}),
        Inbound::Highlight {
            call,
            background,
            foreground,
            last_only,
        } => json!({"type":"highlight","call":call,"background":color(*background),
            "foreground":color(*foreground),"last_only":last_only}),
        Inbound::SwitchConfiguration => json!({"type":"switch_configuration"}),
        Inbound::Configure => json!({"type":"configure"}),
        Inbound::Other(kind) => json!({"type":"other","kind":kind}),
    };
    v["schema"] = json!(d.schema);
    v["id"] = json!(d.id);
    v
}

// Proves: CL-040-01, CL-040-03, TC-012-001
#[test]
fn tc_012_001_wire_vectors() {
    let all = vectors();
    let (mut outbound, mut inbound, mut refused) = (0, 0, 0);
    for (name, v) in &all {
        assert!(
            v["source"]
                .as_str()
                .is_some_and(|s| s.contains("NetworkMessage.hpp")),
            "{name}: source"
        );
        assert_eq!(v["exact"], true, "{name}");
        let bytes = hex(v["hex"].as_str().unwrap());
        match v["direction"].as_str().unwrap() {
            "outbound" => {
                outbound += 1;
                assert_eq!(hex_of(&encode(&v["input"])), hex_of(&bytes), "{name}");
            }
            _ if v["expect"].is_null() => {
                refused += 1;
                assert_eq!(nm::parse(&bytes), None, "{name} must be refused");
            }
            _ => {
                inbound += 1;
                let parsed = nm::parse(&bytes).unwrap_or_else(|| panic!("{name} refused"));
                assert_eq!(shown(&parsed), v["expect"], "{name}");
            }
        }
    }
    // The scan names its surface: every message kind of the vector set was read.
    assert_eq!((outbound, inbound, refused), (8, 18, 9), "vector count");
}
fn hex_of(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

// Proves: CL-040-03, TC-012-001
#[test]
fn tc_012_001_parser_never_panics_and_bounds_input() {
    // Every truncation of every vector, and deterministic pseudo-random datagrams.
    for (_, v) in vectors() {
        let bytes = hex(v["hex"].as_str().unwrap());
        for n in 0..bytes.len() {
            let _ = nm::parse(&bytes[..n]);
        }
    }
    let mut x: u64 = 0x9E37_79B9_7F4A_7C15;
    for round in 0..20_000 {
        let mut data = vec![0xAD, 0xBC, 0xCB, 0xDA, 0, 0, 0, 2 + (round % 2) as u8];
        let n = (round % 96) as usize;
        for _ in 0..n {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            data.push(x as u8);
        }
        let _ = nm::parse(&data);
    }
    // A huge declared utf8 length is refused, not allocated.
    let mut big = hex("adbccbda0000000200000009");
    big.extend_from_slice(&0xFFFF_FFFEu32.to_be_bytes());
    assert_eq!(nm::parse(&big), None);
}
